    try:
        doc = frappe.get_doc({
            "doctype": "Item",
            "item_group": "Consumable",
            "item_name": item_name,
            "item_code": item_name,
            "stock_uom": "Nos",
        })
        doc.insert()
        created.append(doc.name)
    except Exception as e:
        failed.append({"item_name": item_name, "error": str(e)})

if failed:
    result = {"created": False, "error": f"Could not create: {failed}", "created_items": created}
else:
    result = {"created": True, "name": ", ".join(created), "doctype": "Item"}

