missing_items = [i["item_name"] for i in items if not frappe.db.exists("Item", i.get("item_name"))]
if missing_items:
    names = ", ".join(missing_items)
    result = {
        "created": False,
        "error": f"Item '{names}' does not exist.",
        "next_action": {"name": "create_item", "arguments": {"items": names}},
        "then": {"name": "create_stock_entry", "arguments": args},
    }
elif purpose in ("Material Receipt",) and not target_warehouse:
    result = {"created": False, "error": "target_warehouse is required for a Material Receipt."}
elif purpose in ("Material Issue",) and not source_warehouse:
    result = {"created": False, "error": "source_warehouse is required for a Material Issue."}
elif purpose == "Material Transfer" and not (source_warehouse and target_warehouse):
    result = {"created": False, "error": "Both source_warehouse and target_warehouse are required for a Material Transfer."}
else:
    row_items = []
    for i in items:
        row = {"item_code": i["item_name"], "qty": i.get("qty", 1)}
        if source_warehouse:
            row["s_warehouse"] = source_warehouse
        if target_warehouse:
            row["t_warehouse"] = target_warehouse
        row_items.append(row)
    doc = frappe.get_doc({
        "doctype": "Stock Entry",
        "stock_entry_type": purpose,
        "items": row_items,
    })
    doc.insert()
    result = {"created": True, "name": doc.name, "doctype": "Stock Entry"}

