party_type = args.get("party_type")
party = args.get("party")
payment_type = args.get("payment_type") or ("Receive" if party_type == "Customer" else "Pay")
paid_amount = args.get("amount")
paid_from = args.get("paid_from_account")
paid_to = args.get("paid_to_account")

if party_type not in ("Customer", "Supplier"):
    result = {"created": False, "error": "party_type must be 'Customer' or 'Supplier'."}
elif not frappe.db.exists(party_type, party):
    next_fn = "create_customer" if party_type == "Customer" else "create_supplier"
    arg_key = "customer_name" if party_type == "Customer" else "supplier_name"
    result = {
        "created": False,
        "error": f"{party_type} '{party}' does not exist.",
        "next_action": {"name": next_fn, "arguments": {arg_key: party}},
        "then": {"name": "create_payment_entry", "arguments": args},
    }
elif not paid_amount:
    result = {"created": False, "error": "amount is required."}
elif not (paid_from and paid_to):
    # Deliberately not defaulted: guessing a plausible-looking GL account name
    # is how you get money silently posted to the wrong ledger. The caller
    # must supply the real account names from this company's chart of accounts.
    result = {
        "created": False,
        "error": "paid_from_account and paid_to_account are both required -- "
                 "these must be real account names from your Chart of Accounts "
                 "(Accounting > Chart of Accounts), there is no safe default.",
    }
else:
    doc = frappe.get_doc({
        "doctype": "Payment Entry",
        "payment_type": payment_type,
        "party_type": party_type,
        "party": party,
        "paid_amount": paid_amount,
        "received_amount": paid_amount,
        "paid_from": paid_from,
        "paid_to": paid_to,
    })
    doc.insert()
    result = {"created": True, "name": doc.name, "doctype": "Payment Entry"}

accounts = args.get("accounts") or []
posting_date = args.get("posting_date")

if len(accounts) < 2:
    result = {
        "created": False,
        "error": "accounts must have at least 2 rows (a Journal Entry must balance -- "
                 "total debit must equal total credit), e.g. "
                 "[{\"account\": \"Cash - X\", \"debit_in_account_currency\": 100}, "
                 "{\"account\": \"Sales - X\", \"credit_in_account_currency\": 100}]. "
                 "Account names must be real accounts from your Chart of Accounts.",
    }
else:
    total_debit = sum(a.get("debit_in_account_currency", 0) for a in accounts)
    total_credit = sum(a.get("credit_in_account_currency", 0) for a in accounts)
    if round(total_debit, 2) != round(total_credit, 2):
        result = {
            "created": False,
            "error": f"Entry does not balance: total debit {total_debit} != total credit {total_credit}.",
        }
    else:
        doc = frappe.get_doc({
            "doctype": "Journal Entry",
            "posting_date": posting_date or frappe.utils.nowdate(),
            "accounts": accounts,
        })
        doc.insert()
        result = {"created": True, "name": doc.name, "doctype": "Journal Entry"}

