gender = args.get("gender")
date_of_joining = args.get("date_of_joining")
company = args.get("company")

if not first_name:
    result = {"created": False, "error": "first_name is required."}
elif not gender:
    # Not defaulted on purpose: Employee.gender is mandatory in ERPNext HR
    # and guessing it would just be wrong as often as not.
    result = {"created": False, "error": "gender is required (e.g. 'Male', 'Female', 'Other')."}
else:
    if not company:
        companies = frappe.get_all("Company", limit=1, fields=["name"])
        if not companies:
            result = {"created": False, "error": "No Company exists in this system yet -- create one first (outside the agent)."}
            company = None
        else:
            company = companies[0]["name"]
    if company:
        doc = frappe.get_doc({
            "doctype": "Employee",
            "first_name": first_name,
            "last_name": args.get("last_name"),
            "gender": gender,
            "date_of_joining": date_of_joining or frappe.utils.nowdate(),
            "company": company,
        })
        doc.insert()
        result = {"created": True, "name": doc.name, "doctype": "Employee"}

