components = args.get("components") or []
quantity = args.get("quantity", 1)

if not frappe.db.exists("Item", production_item):
    result = {
        "created": False,
        "error": f"Item '{production_item}' does not exist.",
        "next_action": {"name": "create_item", "arguments": {"items": production_item}},
        "then": {"name": "create_bom", "arguments": args},
    }
else:
    missing = [c["item_name"] for c in components if not frappe.db.exists("Item", c.get("item_name"))]
    if missing:
        names = ", ".join(missing)
        result = {
            "created": False,
            "error": f"Component item(s) not found: {names}",
            "next_action": {"name": "create_item", "arguments": {"items": names}},
            "then": {"name": "create_bom", "arguments": args},
        }
    elif not components:
